        _s101_ = string$.x09__u0414__,
        _s151_1 = "\\ln p_{\\text{ws\\_\u0432\u044b\u0445}} = \\frac{C_8}{T_\\text{\u0432\u044b\u0445}} + C_9 + C_{10} T_\\text{\u0432\u044b\u0445} + C_{11} T_\\text{\u0432\u044b\u0445}^2 + C_{12} T_\\text{\u0432\u044b\u0445}^3 + C_{13} \\ln T_\\text{\u0432\u044b\u0445}",
