        _s153_0 = "\\ln p_{\\text{ws\\_\u0432\u0445}} = \\frac{C_1}{T_\\text{\u0432\u0445}} + C_2 + C_3 T_\\text{\u0432\u0445} + C_4 T_\\text{\u0432\u0445}^2 + C_5 T_\\text{\u0432\u0445}^3 + C_6 T_\\text{\u0432\u0445}^4 + C_7 \\ln T_\\text{\u0432\u0445}",
        _s145_0 = "\\ln p_{\\text{ws\\_\u0432\u0445}} = \\frac{C_8}{T_\\text{\u0432\u0445}} + C_9 + C_{10} T_\\text{\u0432\u0445} + C_{11} T_\\text{\u0432\u0445}^2 + C_{12} T_\\text{\u0432\u0445}^3 + C_{13} \\ln T_\\text{\u0432\u0445}",
