        _s48_3 = "\u0420\u0430\u0441\u0447\u0435\u0442 W\u0432\u0445 \u0438 W\u0432\u044b\u0445 \u043f\u0440\u0438\u0432\u0435\u0434\u0435\u043d \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0430\u0445 2.1 \u0438 2.2.",
