        _s95_1 = "\u041d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0432\u043b\u0430\u0436\u043d\u043e\u0441\u0442\u044c (f\u0432\u0445 \u0438\u043b\u0438 f\u0432\u044b\u0445) \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u0440\u0430\u0437\u0434\u0435\u043b\u0443 2.1 \u0438\u043b\u0438 2.2.",
        _s111_ = "\u0418\u0437 \u0413\u043b\u0430\u0432\u044b 1 ASHRAE 2021, 10. \u0422\u0418\u041f\u041e\u0412\u042b\u0415 \u041f\u0420\u041e\u0426\u0415\u0421\u0421\u042b \u041a\u041e\u041d\u0414\u0418\u0426\u0418\u041e\u041d\u0418\u0420\u041e\u0412\u0410\u041d\u0418\u042f \u0412\u041e\u0417\u0414\u0423\u0425\u0410, \u041e\u0445\u043b\u0430\u0436\u0434\u0435\u043d\u0438\u0435 \u0438 \u041e\u0441\u0443\u0448\u0435\u043d\u0438\u0435 \u0412\u043b\u0430\u0436\u043d\u043e\u0433\u043e \u0412\u043e\u0437\u0434\u0443\u0445\u0430:",
        _s70_2 = "m_{\\text{\u0441.\u0432.}}^\xb7 h_1 = m_{\\text{\u0441.\u0432.}}^\xb7 h_2 +  _1 q_2 + m_w^\xb7 h_{w2}",
